    corr = correlation(order_values, width_values)
    return {
        "metric_name": "Correlation",
        "metric_value": corr,
        "instances_tested": len(order_values),
        "n_max": max(n_values),
        "conjecture_holds": corr > 0.9,
        "counterexample": ""
    }

if __name__ == "__main__":
    import sys
